def transform(grid):
    h, w = len(grid), len(grid[0])

    # Split on a uniform row; compare the matching positions in the two panels.
    for r in range(h):
        if len(set(grid[r])) == 1:
            a, b = grid[:r], grid[r + 1:]
            shared = set(x for row in a for x in row) & set(
                x for row in b for x in row)
            color = max(shared, key=lambda x: sum(
                a[i][j] == x and b[i][j] == x
                for i in range(min(len(a), len(b)))
                for j in range(w)))
            return [[3 if a[i][j] == color and b[i][j] == color else color
                     for j in range(w)]
                    for i in range(min(len(a), len(b)))]

    # Otherwise split on a uniform column.
    for c in range(w):
        if all(grid[i][c] == grid[0][c] for i in range(h)):
            a = [row[:c] for row in grid]
            b = [row[c + 1:] for row in grid]
            shared = set(x for row in a for x in row) & set(
                x for row in b for x in row)
            color = max(shared, key=lambda x: sum(
                a[i][j] == x and b[i][j] == x
                for i in range(h)
                for j in range(min(len(a[i]), len(b[i])))))
            return [[3 if a[i][j] == color and b[i][j] == color else color
                     for j in range(min(len(a[i]), len(b[i])))]
                    for i in range(h)]
    return grid
